# name -> (bytes per character, hex-encoded table)
_TABLES = {
    "msx":     (9,  _MSX_INTL),
    "msx-din": (9,  _MSX_DIN),
    "msx-jp":  (9,  _MSX_JP),
    "fx80":    (12, _FX80),
}

#: Charsets that are an MSX character ROM: bytes index the glyph table directly
#: over the full 0x00-0xFF range, so the high bit is data - not an italic flag.
MSX_CHARSETS = frozenset(("msx", "msx-din", "msx-jp"))

NAMES = tuple(_TABLES)
DEFAULT = "msx"


class Font:
    """A printer glyph set. `glyph(code)` -> (columns, start, end)."""

    __slots__ = ("name", "stride", "data", "msx_charset")

    def __init__(self, name):
        if name not in _TABLES:
            raise ValueError(f"unknown charset {name!r} (have: {', '.join(NAMES)})")
        self.stride, hexs = _TABLES[name]
        self.name = name
        self.data = binascii.unhexlify(hexs)
        self.msx_charset = name in MSX_CHARSETS
        assert len(self.data) == 256 * self.stride

    @property
    def columns(self):
        """Glyph columns per character (the attribute byte excluded)."""
        return self.stride - 1

    def glyph(self, code):
        """Columns for `code` plus its proportional span.

        Returns (columns, start, end): `columns` is a list of 9-bit slices with
        the attribute's top-bit shift already applied; printing columns
        [start:end] gives the proportional form, the whole list the fixed one.
        """
        base = (code & 0xFF) * self.stride
        attr = self.data[base]
        shift = attr >> 7
        cols = [c << shift for c in self.data[base + 1:base + self.stride]]
        start = (attr >> 4) & 0x07
        end = attr & 0x0F
        if not 0 <= start < end <= len(cols):        # trust the glyph, not the attr
            start, end = 0, len(cols)
        return cols, start, end


def load(name=DEFAULT):
    return Font(name)
